import {levelForXP} from './progression.mjs';
import {CATALOG,WALLS,FLOORS,PRESETS,VARIANTS} from './catalog.mjs';
import {footprint,serviceTiles,findPath,validateLayout,waitingTiles,sameTile} from './grid.mjs';
import {route,station} from './simulation.mjs';
export function beginEdit(w){return {original:structuredClone(w.clinic),clinic:structuredClone(w.clinic),patients:structuredClone(w.patients),actors:structuredClone([...w.patients,w.doctor,w.receptionist]),cost:0,changedIds:[]};}
export function cancelEdit(w){return w;}
const fail=(draft,reason)=>({draft,result:{ok:false,reason}});
export function previewEdit(draft,op){const d=structuredClone(draft),c=d.clinic;let i=c.items.find(i=>i.id===op.id);if(op.type==='wall'||op.type==='floor'){const list=op.type==='wall'?WALLS:FLOORS;const finish=list.find(f=>f.id===op.value);if(!finish)return fail(draft,'Choose an available finish.');if(levelForXP(c.xp)<finish.unlockLevel)return fail(draft,'This finish unlocks at Level '+finish.unlockLevel+'.');c[op.type+'Id']=op.value;return {draft:d,result:{ok:true}};}
if(op.type==='customize'){
 if(!i)return fail(draft,'Select a furnishing first.');const before={...i},variant=VARIANTS[i.kind]?.find(v=>v.id===op.variantId);
 if(!variant)return fail(draft,'Choose an available style.');if((i.x===null||variant.id!==i.variantId)&&variant.unlockLevel>levelForXP(c.xp))return fail(draft,'This style unlocks at Level '+variant.unlockLevel+'.');
 if(op.stored){if(CATALOG[i.kind].core)return fail(draft,'Essential stations stay in your practice.');if(i.kind==='chair'&&i.x!==null&&c.items.filter(a=>a.kind==='chair'&&a.x!==null).length<=2)return fail(draft,'Keep at least two waiting seats.');}
 Object.assign(i,{x:op.stored?null:op.x,y:op.stored?null:op.y,rotation:op.rotation,variantId:op.variantId});
 const geometryChanged=['x','y','rotation'].some(k=>before[k]!==i[k]);
 if(geometryChanged&&CATALOG[i.kind].blocking&&d.actors.some(p=>footprint(i).some(t=>sameTile(t,p.tile)||sameTile(t,p.path[0]))))return fail(draft,'A patient or staff member is here. Choose a clear tile.');
 if(geometryChanged)d.changedIds=[...new Set([...d.changedIds,i.id])];const valid=validateLayout(c);if(!valid.ok)return fail(draft,valid.reason);if(!actorsReachable(c,d.actors))return fail(draft,'Leave a clear path for every patient and staff member.');return {draft:d,result:valid};
}
if(op.type==='variant'){const v=VARIANTS[i?.kind]?.find(v=>v.id===op.variantId);if(!v)return fail(draft,'Choose an available style.');if(levelForXP(c.xp)<v.unlockLevel)return fail(draft,'This style unlocks at Level '+v.unlockLevel+'.');i.variantId=v.id;return {draft:d,result:{ok:true}};}
if(op.type==='purchase'){const def=CATALOG[op.kind];if(!def?.price)return fail(draft,'This item is already included.');if(c.items.filter(i=>i.kind===op.kind).length>=def.limit)return fail(draft,'You have the maximum number of these.');if(d.cost+def.price>d.original.coins)return fail(draft,'Save a few more coins for this item.');let n=1;while(c.items.some(a=>a.id===op.kind+'-'+n))n++;i={id:op.kind+'-'+n,kind:op.kind,x:op.x,y:op.y,rotation:op.rotation??0,variantId:op.variantId??'default'};const variant=VARIANTS[op.kind]?.find(v=>v.id===i.variantId);if(!variant||variant.unlockLevel>levelForXP(c.xp))return fail(draft,'This style is locked.');c.items.push(i);d.cost+=def.price;}else{if(!i)return fail(draft,'Select a furnishing first.');if(op.type==='store'){if(CATALOG[i.kind].core)return fail(draft,'Essential stations stay in your practice.');if(i.kind==='chair'&&c.items.filter(a=>a.kind==='chair'&&a.x!==null).length<=2)return fail(draft,'Keep at least two waiting seats.');i.x=null;i.y=null;}else if(['move','placeInventory','rotate'].includes(op.type)){if(op.type==='placeInventory'){const variant=VARIANTS[i.kind]?.find(v=>v.id===(i.variantId??'default'));if(!variant||variant.unlockLevel>levelForXP(c.xp))return fail(draft,'This style unlocks at Level '+(variant?.unlockLevel??1)+'.');}i.x=op.x??i.x;i.y=op.y??i.y;i.rotation=op.rotation??i.rotation;if(op.variantId){const v=VARIANTS[i.kind]?.find(v=>v.id===op.variantId);if(!v||v.unlockLevel>levelForXP(c.xp))return fail(draft,'This style is locked.');i.variantId=op.variantId;}}else return fail(draft,'Unknown placement action.');}
if(CATALOG[i.kind].blocking&&d.actors.some(p=>footprint(i).some(t=>sameTile(t,p.tile)||sameTile(t,p.path[0]))))return fail(draft,'A patient or staff member is here. Choose a clear tile.');d.changedIds=[...new Set([...d.changedIds,i.id])];const result=validateLayout(c);if(!result.ok)return fail(draft,result.reason);if(!actorsReachable(c,d.actors))return fail(draft,'Leave a clear path for every patient and staff member.');return {draft:d,result};}
function actorsReachable(clinic,actors){return actors.every(p=>findPath(clinic,p.tile,PRESETS[clinic.presetId].entrance)!==null);}
export function commitEdit(w,draft,transactionId){if(w.transactions.includes(transactionId)||JSON.stringify(w.clinic)!==JSON.stringify(draft.original))return {world:w,result:{ok:false,reason:'This edit has already been applied or your clinic changed.'}};const valid=validateLayout(draft.clinic);if(!actorsReachable(draft.clinic,[...w.patients,w.doctor,w.receptionist]))return {world:w,result:{ok:false,reason:'Leave a clear path for every patient and staff member.'}};if(!valid.ok)return {world:w,result:valid};if(draft.cost>w.clinic.coins)return {world:w,result:{ok:false,reason:'Not enough coins.'}};const copy=structuredClone(w);copy.clinic=structuredClone(draft.clinic);copy.clinic.coins-=draft.cost;copy.transactions.push(transactionId);if(copy.transactions.length>100)copy.transactions.shift();if(!draft.changedIds.length)return {world:copy,result:{ok:true}};const examMoved=draft.changedIds.includes(station(copy,'exam').id),counterMoved=draft.changedIds.includes(station(copy,'counter').id);
for(const p of copy.patients){if(p.stage==='waiting'){const seat=copy.clinic.items.find(i=>i.id===p.seatId&&i.x!==null);if(!seat)p.seatId=null;route(copy,p,seat?serviceTiles(seat).patient:waitingTiles(copy.clinic)[copy.patients.indexOf(p)%Math.max(1,waitingTiles(copy.clinic).length)]??p.tile);}else if(['toExam','seating','exam','standing'].includes(p.stage)&&examMoved){if(p.stage!=='toExam')p.resumeStage=p.stage;p.stage='toExam';route(copy,p,serviceTiles(station(copy,'exam')).patient);}else if(['toReception','toPayment','checkIn','payment'].includes(p.stage)&&counterMoved){const paying=['toPayment','payment'].includes(p.stage);if(['checkIn','payment'].includes(p.stage))p.resumeService={stage:p.stage,remaining:p.remaining};p.stage=paying?'toPayment':'toReception';copy.counter=null;route(copy,p,serviceTiles(station(copy,'counter')).patient);}else if(p.path.length){const goal=p.path.at(-1);p.path=findPath(copy.clinic,p.tile,goal)??[];p.progress=0;}}
route(copy,copy.doctor,serviceTiles(station(copy,'exam')).staff);route(copy,copy.receptionist,serviceTiles(station(copy,'counter')).staff);return {world:copy,result:{ok:true}};}
